import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"测试","description":"","frontmatter":{"title":"测试","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/测试.md","filePath":"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/测试.md"}'),a={name:"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/测试.md"};function s(r,e,i,n,f,l){return t(),d("div",null,[...e[0]||(e[0]=[c('<div><ul><li>文件上传</li><li>进入/etc/fdfs目录，修改client.conf文件，先改名</li><li>mv client.conf.sample client.conf</li><li>vim client.conf</li><li>修改配置：</li><li>==#====需要修改的内容如下==</li></ul><p>base_path=/home/dfs tracker_server=192.168.52.1:22122 #tracker <code>==服务器==</code>IP<code>==和端口==</code> http.tracker_server_port=8080 # tracker <em>服务器的</em> <code>http</code><em>端口号，必须和</em><code>tracker</code><em>的设置对应起来</em></p><p>先在/tmp目录下上传一张照片， 然后执行命令，第二个参数为配置文件，第三个参数为要上传的文件名 /usr/bin/fdfs_upload_file /etc/fdfs/client.conf /tmp/1.jpeg</p><p>命令会返回一个id，表示图片上传成功</p><p><code>其路径是我们storage.conf中配置决定的，文件被存在打散的目录中：</code></p><p><code>data</code>下有<code>256</code>个<code>1</code>级目录，每级目录下又有<code>256</code>个<code>2</code>级子目录，总共<code>65536</code>个文件，新写的文件会以<code>hash</code>的方式被路由到其中某个子目录下，然后将文件数据直接作为一个本地文件存储到该目录中。 ==如要测试文件上传下载，可使用以下命令：== ==fdfs_upload_file /etc/fdfs/client.conf /usr/local/src/n== ==成功后返回：== ==group1/M00/00/00/xx.tar.gz== 然后我们<code>HTTP</code>访问文件</p><p><a href="http://192.168.150.132:8888/group1/M00/00/00/wKiWhFrdeCeAC_vCAABqgowGIFg399.png" target="_blank" rel="noreferrer">http://192.168.150.132:8888/group1/M00/00/00/wKiWhFrdeCeAC_vCAABqgowGIFg399.png</a> 在<code>4.05</code>的时候，就<code>remove embed HTTP support</code></p><h1 id="version-4-05-2012-12-30￼-client-fdfs-upload-file-c-can-specify-storage-ip-port-and-store-path-index￼-add-connection-pool￼-client-load-storage-ids-config￼-common-ini-file-reader-c-does-not-call-chdir￼-keep-the-mtime-of-file-same￼-use-g-current-time-instead-of-call-time-function￼-remove-embed-http-supporthttp请求不能访问文件的原因我们在使用fastdfs部署一个分布式文件系统的时候-通过fastdfs的客户端api来进行文件的上传、下载、删除等操作。同时通过fastdfs的http服务器来提供http服务。但是fastdfs的http服务较为简单-无法提供负载均衡等高性能的服务-所以fastdfs的开发者——淘宝的架构师余庆同学-为我们提供了nginx上使用的fastdfs模块-也可以叫fastdfs的nginx模块-。-fastdfs通过tracker服务器-将文件放在storage服务器存储-但是同组之间的服务器需要复制文件-有延迟的问题-假设tracker服务器将文件上传到了192-168-128-131-文件id已经返回客户端-这时-后台会将这个文件复制到192-168-128-131-如果复制没有完成-客户端就用这个id在192-168-128-131取文件-肯定会出现错误。这个fastdfs-nginx-module可以重定向连接到源服务器取文件-避免客户端由于复制延迟的问题-出现错误。-正是这样-fastdfs需要结合nginx-所以取消原来对http的直接支持。" tabindex="-1">Version 4.05 2012-12-30￼ * client/fdfs_upload_file.c can specify storage ip port and store path index￼ * add connection pool￼ * client load storage ids config￼ * common/ini_file_reader.c does NOT call chdir￼ * keep the mtime of file same￼ * use g_current_time instead of call time function￼ * remove embed HTTP support HTTP <strong>请求不能访问文件的原因</strong> 我们在使用<code>FastDFS</code>部署一个分布式文件系统的时候，通过<code>FastDFS</code>的客户端<code>API</code>来进行文件的上传、下载、删除等操作。同时通过<code>FastDFS</code>的<code>HTTP</code>服务器来提供<code>HTTP</code>服务。但是<code>FastDFS</code>的<code>HTTP</code>服务较为简单，无法提供负载均衡等高性能的服务，所以<code>FastDFS</code>的开发者——淘宝的架构师余庆同学，为我们提供了<code>Nginx</code>上使用的<code>FastDFS</code>模块（也可以叫<code>FastDFS</code>的<code>Nginx</code>模块）。  <code>FastDFS</code>通过<code>Tracker</code>服务器<code>,</code>将文件放在<code>Storage</code>服务器存储<code>,</code>但是同组之间的服务器需要复制文件<code>,</code>有延迟的问题<code>.</code>假设<code>Tracker</code>服务器将文件上传到了<code>192.168.128.131,</code>文件<code>ID</code>已经返回客户端<code>,</code>这时<code>,</code>后台会将这个文件复制到<code>192.168.128.131,</code>如果复制没有完成<code>,</code>客户端就用这个<code>ID</code>在<code>192.168.128.131</code>取文件<code>,</code>肯定会出现错误。这个<code>fastdfs-nginx-module</code>可以重定向连接到源服务器取文件<code>,</code>避免客户端由于复制延迟的问题<code>,</code>出现错误。  正是这样，<code>FastDFS</code>需要结合<code>nginx</code>，所以取消原来对<code>HTTP</code>的直接支持。 <a class="header-anchor" href="#version-4-05-2012-12-30￼-client-fdfs-upload-file-c-can-specify-storage-ip-port-and-store-path-index￼-add-connection-pool￼-client-load-storage-ids-config￼-common-ini-file-reader-c-does-not-call-chdir￼-keep-the-mtime-of-file-same￼-use-g-current-time-instead-of-call-time-function￼-remove-embed-http-supporthttp请求不能访问文件的原因我们在使用fastdfs部署一个分布式文件系统的时候-通过fastdfs的客户端api来进行文件的上传、下载、删除等操作。同时通过fastdfs的http服务器来提供http服务。但是fastdfs的http服务较为简单-无法提供负载均衡等高性能的服务-所以fastdfs的开发者——淘宝的架构师余庆同学-为我们提供了nginx上使用的fastdfs模块-也可以叫fastdfs的nginx模块-。-fastdfs通过tracker服务器-将文件放在storage服务器存储-但是同组之间的服务器需要复制文件-有延迟的问题-假设tracker服务器将文件上传到了192-168-128-131-文件id已经返回客户端-这时-后台会将这个文件复制到192-168-128-131-如果复制没有完成-客户端就用这个id在192-168-128-131取文件-肯定会出现错误。这个fastdfs-nginx-module可以重定向连接到源服务器取文件-避免客户端由于复制延迟的问题-出现错误。-正是这样-fastdfs需要结合nginx-所以取消原来对http的直接支持。" aria-label="Permalink to &quot;Version 4.05  2012-12-30￼ * client/fdfs_upload_file.c can specify storage ip port and store path index￼ * add connection pool￼ * client load storage ids config￼ * common/ini_file_reader.c does NOT call chdir￼ * keep the mtime of file same￼ * use g_current_time instead of call time function￼ * remove embed HTTP support\nHTTP\n**请求不能访问文件的原因**\n我们在使用`FastDFS`部署一个分布式文件系统的时候，通过`FastDFS`的客户端`API`来进行文件的上传、下载、删除等操作。同时通过`FastDFS`的`HTTP`服务器来提供`HTTP`服务。但是`FastDFS`的`HTTP`服务较为简单，无法提供负载均衡等高性能的服务，所以`FastDFS`的开发者——淘宝的架构师余庆同学，为我们提供了`Nginx`上使用的`FastDFS`模块（也可以叫`FastDFS`的`Nginx`模块）。 \n`FastDFS`通过`Tracker`服务器`,`将文件放在`Storage`服务器存储`,`但是同组之间的服务器需要复制文件`,`有延迟的问题`.`假设`Tracker`服务器将文件上传到了`192.168.128.131,`文件`ID`已经返回客户端`,`这时`,`后台会将这个文件复制到`192.168.128.131,`如果复制没有完成`,`客户端就用这个`ID`在`192.168.128.131`取文件`,`肯定会出现错误。这个`fastdfs-nginx-module`可以重定向连接到源服务器取文件`,`避免客户端由于复制延迟的问题`,`出现错误。 \n正是这样，`FastDFS`需要结合`nginx`，所以取消原来对`HTTP`的直接支持。&quot;">​</a></h1><p>报错： ==ERROR - file: tracker_proto.c, line: 48, server: 109.24.249.40:22122, response status 2 != 0== ==tracker_query_storage fail, error no: 2, error info: No such file or directory== ==解决：杀死进程并重启== ==pkill -9 fdfs== ==/usr/bin/fdfs_trackerd /etc/fdfs/tracker.conf== ==/usr/bin/fdfs_storaged /etc/fdfs/storage.conf==</p></div>',1)])])}const g=o(a,[["render",s]]);export{m as __pageData,g as default};
